prompt.text:
Repair the complete CommonJS source below. Export exactly `{ createLogPolicy }` in the corrected source.

`createLogPolicy(blockedTags)` requires an array containing only strings and throws `TypeError` otherwise. It must snapshot the array and return a function `shouldKeep(entry)`. That function requires a plain object with string properties `tag` and `message`; malformed entries throw `TypeError`. It returns `false` when `entry.tag` equals a blocked tag under case-insensitive exact comparison, and `true` otherwise. No trimming or substring matching occurs. An empty blocked array permits every valid entry. Later mutation of the source array must not change the policy, and neither function may mutate caller data.

```javascript
function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function createLogPolicy(blockedTags) {
  if (!Array.isArray(blockedTags) || blockedTags.some((tag) => typeof tag !== 'string')) {
    throw new TypeError('blockedTags must be a string array');
  }
  const blocked = new Set(blockedTags.map((tag) => tag.toLowerCase()));

  return function shouldKeep(entry) {
    if (!isPlainObject(entry) || typeof entry.tag !== 'string' || typeof entry.message !== 'string') {
      throw new TypeError('entry must contain string tag and message properties');
    }
    return !blocked.has(entry.tag);
  };
}

module.exports = { createLogPolicy };
```

