'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['createLogPolicy']);
const { createLogPolicy } = api;

for (const invalid of [null, {}, 'tag', [1], ['ok', null]]) {
  assert.throws(() => createLogPolicy(invalid), TypeError);
}
const source = ['Debug', 'SECURITY'];
const shouldKeep = createLogPolicy(source);
source[0] = 'info';
source.push('audit');
assert.strictEqual(shouldKeep({ tag: 'debug', message: '' }), false);
assert.strictEqual(shouldKeep({ tag: 'DeBuG', message: 'x' }), false);
assert.strictEqual(shouldKeep({ tag: 'security', message: 'x' }), false);
assert.strictEqual(shouldKeep({ tag: 'info', message: 'x' }), true);
assert.strictEqual(shouldKeep({ tag: 'audit', message: 'x' }), true);
assert.strictEqual(shouldKeep({ tag: ' debug', message: 'x' }), true);
assert.strictEqual(shouldKeep({ tag: 'debug-extra', message: 'x' }), true);

const entry = { tag: 'INFO', message: 'unchanged', extra: 1 };
assert.strictEqual(shouldKeep(entry), true);
assert.deepStrictEqual(entry, { tag: 'INFO', message: 'unchanged', extra: 1 });
for (const invalid of [null, [], {}, { tag: 1, message: 'x' }, { tag: 'x', message: null }]) {
  assert.throws(() => shouldKeep(invalid), TypeError);
}
const nullPrototypeEntry = Object.create(null);
nullPrototypeEntry.tag = 'debug';
nullPrototypeEntry.message = 'x';
assert.strictEqual(shouldKeep(nullPrototypeEntry), false);
const permitAll = createLogPolicy([]);
assert.strictEqual(permitAll({ tag: '', message: '' }), true);

